// Hero boards and leaflets on the hero pages. The list is generated by
// scripts/rulebook/hero-media.py (data/hero-media.ts). Pure and browser-safe.

export type HeroMediaItem = {
  kind: "board" | "leaflet";
  /** Which one it is, for heroes with two (e.g. the two sides of a board). */
  label: string | null;
  /** File name without extension in public/szabalytar/img/heroes/boards/. */
  file: string;
  width: number;
  height: number;
};

const FOLDER = "/szabalytar/img/heroes/boards";

export const mediaSrc = (item: Pick<HeroMediaItem, "file">) => `${FOLDER}/${item.file}.webp`;
export const mediaThumbSrc = (item: Pick<HeroMediaItem, "file">) => `${FOLDER}/${item.file}-thumb.webp`;

export function mediaLabel(item: Pick<HeroMediaItem, "kind" | "label">): string {
  const name = item.kind === "board" ? "Hős tábla" : "Hős kiskönyv";
  return item.label ? `${name} · ${item.label}` : name;
}

/** A hero page's body around the media section, which goes before the first heading (Tokenek). */
export function splitHeroBody(html: string): [string, string] {
  const at = html.indexOf("<h3");
  return at < 0 ? [html, ""] : [html.slice(0, at), html.slice(at)];
}
